SELECT idx_info.INDX_SNAME AS `指数名称`, idx_info.INDX_CODE AS `指数代码`, DATE_FORMAT(mkt.TRADEDATE, '%Y-%m-%d') AS `交易日期`, ROUND(mkt.CHNG_PCT, 2) AS `日涨跌幅(%)` FROM GET_INDX_GEN_INFO idx_info INNER JOIN INDX_MKT mkt ON idx_info.INNER_CODE = mkt.INNER_CODE WHERE (idx_info.INDX_CODE = '000016' OR idx_info.INDX_SNAME LIKE '%中证白酒%' OR idx_info.INDX_SNAME LIKE '%中证医疗%') AND mkt.TRADEDATE = '2026-09-02' AND idx_info.USE_STATUS = '使用' AND idx_info.ISVALID = 1 AND mkt.ISVALID = 1 AND mkt.CHNG_PCT IS NOT NULL ORDER BY mkt.CHNG_PCT DESC LIMIT 1;
